#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

int n, t;
struct point
{
    int row, col;
};

struct edge
{
    int node, capacity;
};

int delta_x[] = {-1, 0, 1, 0, 0};
int delta_y[] = {0, 1, 0, -1, 0};

bool valid(int x, int y)
{
    return (x >= 0 && x < n && y >= 0 && y < n);
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> t;
    vector<string> first_map(n), second_map(n);
    for (int i = 0; i < n; ++i)
        cin >> first_map[i];
    for (int i = 0; i < n; ++i)
        cin >> second_map[i];
    vector< vector<int> > dist(n, vector<int>(n, 1000));
    point start_point;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (first_map[i][j] == 'Z')
                start_point = {i, j};
    queue<point> q;
    dist[start_point.x][start_point.y] = 0;
    q.push(start_point);
    while (!q.empty())
    {
        point curr = q.front();
        q.pop();
        for (int dir = 0; dir < 4; ++dir)
        {
            point neighbor = {curr.x + delta_x[dir], curr.y + delta_y[dir]};
            if (valid(neighbor.x, neighbor.y) && first_map[neighbor.x][neighbor.y] >= '0' && first_map[neighbor.x][neighbor.y] <= '9' && dist[neighbor.x][neighbor.y] == 1000)
            {
                dist[neighbor.x][neighbor.y] = dist[curr.x][curr.y] + 1;
                q.push(neighbor);
            }
        }
    }
    bool reachable_states[60][10][10][10][10];
    for (int i = 0; i < 60; ++i)
        for (int j = 0; j < 10; ++j)
            for (int k = 0; k < 10; ++k)
                for (int l = 0; l < 10; ++l)
                    for (int m = 0; m < 10; ++m)
                        reachable_states[i][j][k][l][m] = false;
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            for (int k = 0; k < 5; ++k)
            {
                int l = i + delta_x[k], m = j + delta_y[k];
                if (valid(l, m) && first_map[i][j] >= '0' && first_map[i][j] <= '9' && first_map[l][m] >= '0' && first_map[l][m] <= '9')
                    reachable_states[0][i][j][l][m] = true;
            }
        }
    }
    for (int step = 0; step <= t - 2; ++step)
    {
        for (int i = 0; i < n; ++i)
        {
            for (int j = 0; j < n; ++j)
            {
                for (int k = 0; k < n; ++k)
                {
                    for (int l = 0; l < n; ++l)
                    {
                        if (!reachable_states[step][i][j][k][l])
                            continue;
                        for (int o = 0; o < 5; ++o)
                        {
                            int p = k + delta_x[o], r = l + delta_y[o];
                            if (valid(p, r) && first_map[p][r] >= '0' && first_map[p][r] <= '9' && dist[k][l] >= step + 2 && dist[p][r] >= step + 2)
                                reachable_states[step + 1][i][j][p][r] = true;
                        }
                    }
                }
            }
        }
    }
    vector<point> points;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (first_map[i][j] >= '0' && first_map[i][j] <= '9')
                points.push_back({i, j});
    int total_nodes = 2 * (int)points.size() + 2;
    vector<vector<edge>> graph(total_nodes);
    for (int i = 0; i < (int)points.size(); ++i)
    {
        graph[0].push_back({i + 1, first_map[points[i].x][points[i].y] - '0'});
        graph[i + 1].push_back({0, 0});
        graph[(int)points.size() + 1 + i].push_back({total_nodes - 1, second_map[points[i].x][points[i].y] - '0'});
        graph[total_nodes - 1].push_back({(int)points.size() + 1 + i, 0});
    }
    for (int i = 0; i < (int)points.size(); ++i)
    {
        for (int j = 0; j < (int)points.size(); ++j)
        {
            bool can_reach = false;
            for (int k = 0; k <= t - 1; ++k)
                can_reach |= reachable_states[k][points[i].x][points[i].y][points[j].x][points[j].y];
            if (can_reach)
            {
                graph[i + 1].push_back({(int)points.size() + 1 + j, 1000});
                graph[(int)points.size() + 1 + j].push_back({i + 1, 0});
            }
        }
    }
    int max_flow_value = 0;
    while (true)
    {
        vector<bool> visited(total_nodes, false);
        queue<int> q;
        visited[0] = true;
        q.push(0);
        vector<int> parent(total_nodes, -1);
        while (!q.empty())
        {
            int u = q.front();
            q.pop();
            for (auto &e : graph[u])
            {
                if (!visited[e.node] && e.capacity > 0)
                {
                    visited[e.node] = true;
                    parent[e.node] = u;
                    q.push(e.node);
                }
            }
        }
        if (parent[total_nodes - 1] == -1)
            break;
        vector<int> path;
        for (int v = total_nodes - 1; v != -1; v = parent[v])
            path.push_back(v);
        reverse(path.begin(), path.end());
        int flow = 1000;
        for (size_t i = 0; i + 1 < path.size(); ++i)
        {
            int u = path[i], v = path[i + 1];
            for (auto &e : graph[u])
                if (e.node == v)
                {
                    flow = min(flow, e.capacity);
                    break;
                }
        }
        max_flow_value += flow;
        for (size_t i = 0; i + 1 < path.size(); ++i)
        {
            int u = path[i], v = path[i + 1];
            for (auto &e : graph[u])
                if (e.node == v)
                {
                    e.capacity -= flow;
                    break;
                }
            for (auto &e : graph[v])
                if (e.node == u)
                {
                    e.capacity += flow;
                    break;
                }
        }
    }
    cout << max_flow_value;
    return 0;
}
